import Foundation

actor Counter {
    private var value = 0        // 隔离状态，外部不能直接访问

    func increment() {
        value += 1               // 在 actor 内部可以自由读写
    }

    func current() -> Int {
        return value
    }
}

// 串行访问
let counter = Counter()
await counter.increment()
await counter.increment()
print(await counter.current())

// 并发访问：100 个任务同时加，actor 会排队执行
let shared = Counter()
await withTaskGroup(of: Void.self) { group in
    for _ in 1...100 {
        group.addTask { await shared.increment() }
    }
}
print(await shared.current())

