import Foundation

// 一个可变的引用类型，没有任何同步保护
final class RunoobCounter {
    var value = 0
}

func runoobDemo() {
    let counter = RunoobCounter()
    let group = DispatchGroup()

    for _ in 0..<1000 {
        group.enter()
        DispatchQueue.global().async {
            counter.value += 1   // 多条线程同时写同一块内存：数据竞争
            group.leave()
        }
    }
    group.wait()
    print(counter.value)
}
