import Foundation

struct RunoobPoint {
    var x: Int
    var y: Int
}

/// 计算从 start 到 end 的位移向量。
/// - Parameters:
///   - start: 起点坐标。
///   - end: 终点坐标。
/// - Returns: 由 end 减 start 得到的新坐标。
func move(from start: RunoobPoint, to end: RunoobPoint) -> RunoobPoint {
    return RunoobPoint(x: end.x - start.x, y: end.y - start.y)
}

// 调用处读起来就是「从 A 移到 B」，参数标签承担了可读性
let delta = move(from: RunoobPoint(x: 1, y: 1), to: RunoobPoint(x: 4, y: 5))
print("位移：\(delta.x), \(delta.y)")

extension RunoobPoint {
    // 参数标签 by 让调用处读成「按 factor 缩放」
    func scaled(by factor: Int) -> RunoobPoint {
        return RunoobPoint(x: x * factor, y: y * factor)
    }
}

print(RunoobPoint(x: 2, y: 3).scaled(by: 4))

